<script lang="ts">
 import {page} from '$app/state';
 import type {AccountPreferences,AccountProfilesGateway} from '../application/account-profiles';
 import type {ReaderPlatform,ReaderPreferences} from '$lib/features/reading/application/reader';
 import GoogleLink from '$lib/features/identity/presentation/GoogleLink.svelte';
 import type {GoogleLinkGateway} from '$lib/features/identity/application/google-link';
 import AvatarEditor from '$lib/features/identity/presentation/AvatarEditor.svelte';
 import type {AvatarGateway} from '$lib/features/identity/application/avatars';
 import {onMount,onDestroy,untrack} from 'svelte';
 import {goto,invalidateAll} from '$app/navigation';
 import type {AuthGateway,AuthResult} from '$lib/features/identity/application/auth';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {ThemeStore} from '../application/theme';
 import {initializeTheme,changeTheme,changeMotion} from '../application/theme';
 import type {Theme} from '../domain/theme';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {errorText} from '$lib/shared/presentation/messages';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 import ChoiceChips from '$lib/shared/presentation/ui/ChoiceChips.svelte';
 import Button from '$lib/shared/presentation/ui/Button.svelte';
 import ActionLink from '$lib/shared/presentation/ui/ActionLink.svelte';
 import StateMessage from '$lib/shared/presentation/ui/StateMessage.svelte';
 let {user,auth,preferences,avatars,googleLink,accountProfiles,reading}:{user:Account|null;auth:AuthGateway;preferences:ThemeStore;avatars?:AvatarGateway;googleLink?:GoogleLinkGateway;accountProfiles:AccountProfilesGateway;reading?:Pick<ReaderPlatform,'preferences'|'savePreferences'>}=$props();
 const {locale,change}=useLocale();
 const tabs=[['appearance','Көрініс','Вид'],['account','Аккаунт','Аккаунт'],['privacy','Құпиялық','Приватность'],['notifications','Хабарлар','Уведомления'],['reading','Оқу','Чтение']];
 let section=$derived(page.url.searchParams.get('section')||'appearance');
 let accountPrefs=$state<AccountPreferences|null>(null),prefsError=$state(''),prefsSaved=$state(false),prefsBusy=$state(false),readerPrefs=$state<ReaderPreferences|null>(null);
 let generation=0;
 let activeAccountId:string|undefined;
 function current(accountId:string,sequence:number){return sequence===generation&&user?.id===accountId;}
 async function loadPreferences(){if(!user)return;const accountId=user.id,sequence=generation;prefsError='';try{const loaded=await accountProfiles.preferences(accountId);if(current(accountId,sequence))accountPrefs=loaded;}catch{if(current(accountId,sequence))prefsError=text($locale,'Баптаулар жүктелмеді. Қайта көріңіз.','Не удалось загрузить настройки. Повторите.');}}
 async function savePreferences(){if(!user||!accountPrefs||prefsBusy)return;const accountId=user.id,sequence=generation,draft={...accountPrefs};prefsBusy=true;prefsSaved=false;prefsError='';try{const saved=await accountProfiles.save(accountId,draft);if(current(accountId,sequence)){accountPrefs=saved;prefsSaved=true;}}catch{if(current(accountId,sequence))prefsError=text($locale,'Сақталмады. Нұсқалар қайшылығында бетті қайта ашпас бұрын мәтініңізді көшіріп алыңыз.','Не сохранено. При конфликте версий скопируйте текст перед перезагрузкой страницы.');}finally{if(current(accountId,sequence))prefsBusy=false;}}
 function saveReader(){if(reading&&readerPrefs)reading.savePreferences(readerPrefs);}
 let motion=$state(false);
 let theme=$state<Theme>('system'),busy=$state(false),result=$state<AuthResult|null>(null);
 let displayName=$state(''),profileResult=$state<AuthResult|null>(null);
 onMount(()=>{theme=initializeTheme(preferences);motion=preferences.readMotion?.()||false;if(reading)readerPrefs=reading.preferences('manga');});
 $effect(()=>{const accountId=user?.id;untrack(()=>{if(accountId===activeAccountId)return;activeAccountId=accountId;generation++;accountPrefs=null;prefsError='';prefsSaved=false;prefsBusy=false;busy=false;result=null;profileResult=null;displayName=user?.displayName||'';if(accountId)void loadPreferences();});});
 onDestroy(()=>{generation++;});
 async function saveProfile(){if(!user||busy)return;const accountId=user.id,sequence=generation;busy=true;try{const saved=await auth.updateProfile(accountId,displayName);if(!current(accountId,sequence))return;profileResult=saved;if(saved.ok)await invalidateAll();}finally{if(current(accountId,sequence))busy=false;}}
 async function logout(){if(!user||busy)return;const accountId=user.id,sequence=generation;busy=true;try{const saved=await auth.logout();if(!current(accountId,sequence))return;result=saved;if(saved.ok){await invalidateAll();await goto('/');}}finally{if(current(accountId,sequence))busy=false;}}
 async function resend(){if(!user||busy)return;const accountId=user.id,sequence=generation,email=user.email;busy=true;try{const saved=await auth.resend(email);if(current(accountId,sequence))result=saved;}finally{if(current(accountId,sequence))busy=false;}}

</script>
<svelte:head><title>{text($locale,'Баптаулар','Настройки')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<SectionHeading level={1} title={text($locale,'Баптаулар','Настройки')}/>
<div class="settings"><header class="settings-intro"><p class="muted">{text($locale,'Аккаунт, оқу тәжірибесі және құпиялық.','Аккаунт, чтение и приватность.')}</p>{#if user}<ActionLink href={'/users/'+encodeURIComponent(user.id)}>{text($locale,'Профильді көру','Посмотреть профиль')}</ActionLink>{/if}</header>
 <nav class="settings-tabs" aria-label={text($locale,'Баптау бөлімдері','Разделы настроек')}>{#each tabs as tab}<a href={'?section='+tab[0]} aria-current={section===tab[0]?'page':undefined}>{text($locale,tab[1],tab[2])}</a>{/each}</nav>
 {#if section==='account'}
 <section><h2>Аккаунт</h2>{#if user}<p class="account-email">{user.email}</p><p class="muted">{user.verified?text($locale,'Пошта расталған','Почта подтверждена'):text($locale,'Пошта расталмаған','Почта не подтверждена')}</p>
 {#if avatars}{#key user.id}<AvatarEditor gateway={avatars} kind="user" actorId={user.id} ownerId={user.id} name={user.displayName||'Q'}/>{/key}{/if}
 <form class="profile-form" onsubmit={event=>{event.preventDefault();void saveProfile();}}><label for="profile-name">{text($locale,'Көрінетін атың','Публичное имя')}</label><input id="profile-name" bind:value={displayName} maxlength="40" autocomplete="nickname" aria-describedby="profile-hint"/><p id="profile-hint" class="muted">{text($locale,'Пікірлерде және команда құрамында көрінеді. Поштаңды жазба.','Видно в комментариях и составе команды. Не указывай почту.')}</p><Button type="submit" {busy}>{text($locale,'Атын сақтау','Сохранить имя')}</Button></form>
 {#if profileResult}<StateMessage kind={profileResult.ok?'success':'error'} title={profileResult.ok?text($locale,'Атыңыз сақталды','Имя сохранено'):errorText($locale,profileResult.code)}/>{/if}
 {#if googleLink}{#key user.id}<GoogleLink gateway={googleLink} accountId={user.id} verified={user.verified}/>{/key}{/if}
 <div class="settings-links"><ActionLink href="/reports">{text($locale,'Менің өтініштерім','Мои обращения')}</ActionLink>{#if !user.verified}<Button {busy} onclick={resend}>{text($locale,'Растау хатын жіберу','Отправить подтверждение')}</Button>{/if}<ActionLink href="/studio">{text($locale,'Аудармашы кабинеті','Кабинет переводчика')}</ActionLink>{#if user.role==='admin'}<ActionLink href="/admin">{text($locale,'Әкімші панелі','Администрирование')}</ActionLink>{/if}{#if user.role==='admin'||user.role==='moderator'}<ActionLink href="/moderation">{text($locale,'Модерация','Модерация')}</ActionLink>{/if}<Button onclick={logout} {busy} variant="ghost">{text($locale,'Шығу','Выйти')}</Button></div>
 {:else}<p class="muted">{text($locale,'Кітапхана мен оқу орнын басқа құрылғыларда да сақтау үшін кір.','Войди, чтобы сохранить библиотеку и место чтения на других устройствах.')}</p><div class="settings-links"><ActionLink href="/login" variant="primary">{text($locale,'Кіру','Войти')}</ActionLink><ActionLink href="/register">{text($locale,'Тіркелу','Регистрация')}</ActionLink></div>{/if}
 {#if result}<StateMessage kind={result.ok?'success':'error'} title={result.ok?text($locale,'Дайын. Поштаңды тексер.','Готово. Проверь почту.'):errorText($locale,result.code)}/>{/if}</section>
 {/if}{#if section==='appearance'}<section><h2>{text($locale,'Сыртқы көрініс','Внешний вид')}</h2>
 <div class="appearance-setting" id="ui-language"><h3>{text($locale,'Интерфейс тілі','Язык интерфейса')}</h3><ChoiceChips label={text($locale,'Интерфейс тілі','Язык интерфейса')} value={$locale} options={[{value:'kk',label:'Қазақша'},{value:'ru',label:'Русский'}]} onchoose={value=>change(value==='ru'?'ru':'kk')}/></div>
 <div class="appearance-setting" id="ui-theme"><h3>{text($locale,'Тақырып','Тема')}</h3><ChoiceChips label={text($locale,'Тақырып','Тема')} value={theme} options={[{value:'system',label:text($locale,'Авто','Авто'),icon:'monitor'},{value:'dark',label:text($locale,'Қараңғы','Тёмная'),icon:'moon'},{value:'light',label:text($locale,'Жарық','Светлая'),icon:'sun'}]} onchoose={value=>theme=changeTheme(preferences,value)}/></div>
 {#if preferences.readMotion&&preferences.saveMotion&&preferences.applyMotion}<label class="toggle">{text($locale,'Қозғалысты азайту','Уменьшить движение')}<input type="checkbox" bind:checked={motion} onchange={()=>motion=changeMotion(preferences,motion)}/></label>{/if}
 </section>
 {/if}{#if section==='reading'}<section><h2>{text($locale,'Оқу','Чтение')}</h2>{#if readerPrefs}<label class="field">{text($locale,'Оқу режимі','Режим чтения')}<select bind:value={readerPrefs.mode} onchange={saveReader}><option value="pages">{text($locale,'Бет бойынша','По страницам')}</option><option value="strip">{text($locale,'Тік айналдыру','Вертикальная лента')}</option></select></label><label class="field">{text($locale,'Оқу бағыты','Направление чтения')}<select bind:value={readerPrefs.direction} onchange={saveReader}><option value="auto">{text($locale,'Әдепкі','По умолчанию')}</option><option value="ltr">{text($locale,'Солдан оңға','Слева направо')}</option><option value="rtl">{text($locale,'Оңнан солға','Справа налево')}</option></select></label><label class="toggle">{text($locale,'Оқу орнын сақтау','Сохранять прогресс')}<input type="checkbox" bind:checked={readerPrefs.saveProgress} onchange={saveReader}/></label><label class="toggle">{text($locale,'Келесі тарауды алдын ала жүктеу','Загружать следующую главу заранее')}<input type="checkbox" bind:checked={readerPrefs.prefetchNext} onchange={saveReader}/></label><p class="muted reading-hint">{text($locale,'Жылдам қосылымда, трафикті үнемдеу өшірулі болғанда.','При быстром соединении без экономии трафика.')}</p>{/if}<div class="settings-links"><ActionLink href="/saved">{text($locale,'Сақталған тараулар','Скачанные главы')}</ActionLink><ActionLink href="/library">{text($locale,'Кітапхана','Библиотека')}</ActionLink></div></section>
{/if}
 {#if section==='account'||section==='privacy'||section==='notifications'}
 {#if user}{#if accountPrefs}<section class="preference-panel"><fieldset disabled={prefsBusy}>
 {#if section==='account'}<label class="field" for="account-bio">{text($locale,'Қысқаша био','О себе')}<textarea id="account-bio" maxlength="500" rows="4" bind:value={accountPrefs.bio}></textarea></label>{/if}
 {#if section==='privacy'}<h2>{text($locale,'Құпиялық','Приватность')}</h2>{#each [['public_profile','Жария профиль','Публичный профиль'],['show_library','Оқу тізімдерін көрсету','Показывать библиотеку'],['show_activity','Оқу белсенділігін көрсету','Показывать активность'],['allow_follow','Жазылуға рұқсат беру','Разрешить подписки']] as item}<label class="toggle">{text($locale,item[1],item[2])}<input type="checkbox" bind:checked={accountPrefs[item[0] as 'public_profile'|'show_library'|'show_activity'|'allow_follow']}/></label>{/each}<p class="privacy-note">{text($locale,'Пошта, сақталған тараулар және жеке баптаулар жария профильде көрсетілмейді.','Почта, скачанные главы и личные настройки не отображаются в публичном профиле.')}</p>{/if}
 {#if section==='notifications'}<h2>{text($locale,'Хабарлар','Уведомления')}</h2>{#each [['notify_releases','Жаңа тараулар','Новые главы'],['notify_replies','Пікірге жауаптар','Ответы на комментарии'],['notify_followers','Жаңа жазылушылар','Новые подписчики'],['email_digest','Апталық пошта хабарламалары','Еженедельная почтовая рассылка']] as item}<label class="toggle">{text($locale,item[1],item[2])}<input type="checkbox" bind:checked={accountPrefs[item[0] as 'notify_releases'|'notify_replies'|'notify_followers'|'email_digest']}/></label>{/each}{/if}
 </fieldset><Button busy={prefsBusy} onclick={savePreferences}>{text($locale,'Өзгерістерді сақтау','Сохранить изменения')}</Button>{#if prefsSaved}<StateMessage kind="success" title={text($locale,'Өзгерістер сақталды','Изменения сохранены')}/>{/if}</section>{:else if !prefsError}<p class="muted">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}{:else if section!=='account'}<ActionLink href="/login">{text($locale,'Баптаулар үшін кіріңіз','Войдите для настройки')}</ActionLink>{/if}
 {#if prefsError}<StateMessage kind="error" title={prefsError}/>{#if !accountPrefs}<Button onclick={loadPreferences}>{text($locale,'Қайта көру','Повторить')}</Button>{/if}{/if}{/if}
</div>
<style>.reading-hint{font-size:12px;margin-top:8px}fieldset{border:0;margin:0;padding:0;min-width:0}.settings-intro{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.settings-tabs{display:flex;flex-wrap:wrap;gap:8px;padding-bottom:20px;margin-bottom:24px;border-bottom:1px solid var(--line)}.settings-tabs a{display:flex;align-items:center;min-height:44px;padding:0 13px;border:1px solid var(--line);border-radius:8px;color:var(--muted)}.settings-tabs a[aria-current]{color:var(--accent);border-color:var(--accent)}.field{display:grid;gap:10px;margin-bottom:20px}.field select,.field textarea{width:100%;min-height:44px}.toggle{display:flex;align-items:center;justify-content:space-between;gap:20px;min-height:66px;border-bottom:1px solid var(--line);padding:10px 0;cursor:pointer}.toggle input{width:44px;height:44px;accent-color:var(--accent);flex-shrink:0}.preference-panel{padding:20px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.privacy-note{font-size:13px;color:var(--muted);margin:20px 0}.preference-panel :global(button){margin-top:20px}@media(max-width:480px){.settings-intro{align-items:start;flex-direction:column}}.appearance-setting{display:grid;gap:10px;padding:16px 0;border-bottom:1px solid var(--line)}.appearance-setting h3{font-size:14px;font-weight:550}.profile-form{display:grid;gap:12px;margin-top:20px}.profile-form :global(button){justify-self:start}.settings { max-width:720px; } section { margin-bottom:32px; } h2 { margin-bottom:16px; } .settings-links { display:flex; flex-wrap:wrap; gap:8px; margin-top:16px; } .account-email { overflow-wrap:anywhere; margin-bottom:4px; }</style>
